import{_ as e,o as s,c as t,a2 as a}from"./chunks/framework.Buc7gXeZ.js";const k=JSON.parse('{"title":"Visibility & Authorization","description":"","frontmatter":{},"headers":[],"relativePath":"dynamic-table/visibility-authorization.md","filePath":"dynamic-table/visibility-authorization.md"}'),l={name:"dynamic-table/visibility-authorization.md"};function n(o,i,h,d,r,c){return s(),t("div",null,[...i[0]||(i[0]=[a('<h1 id="visibility-authorization" tabindex="-1">Visibility &amp; Authorization <a class="header-anchor" href="#visibility-authorization" aria-label="Permalink to &quot;Visibility &amp; Authorization&quot;">​</a></h1><p>Column visibility is a <strong>security boundary</strong>, not a display preference. This page explains the four states a column can be in and exactly what &quot;unauthorized&quot; excludes.</p><h2 id="the-four-states" tabindex="-1">The four states <a class="header-anchor" href="#the-four-states" aria-label="Permalink to &quot;The four states&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>How it&#39;s set</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Authorized and visible</strong></td><td>Default</td><td>Shown, in SQL select, searchable/sortable if configured, in column manager</td></tr><tr><td><strong>Authorized but hidden by default</strong></td><td><code>-&gt;hiddenByDefault()</code></td><td>Exists, authorized, but starts hidden until the user toggles it on</td></tr><tr><td><strong>Authorized and user-hidden</strong></td><td>User toggles it off via the column manager</td><td>Same as above, driven by user preference instead of the definition</td></tr><tr><td><strong>Not authorized — completely unavailable</strong></td><td><code>-&gt;visible(false)</code> or <code>-&gt;visible(fn () =&gt; bool)</code> returning <code>false</code></td><td>Treated as if the column does not exist, anywhere</td></tr><tr><td><strong>Fixed column, not toggleable</strong></td><td><code>-&gt;toggleable(false)</code></td><td>Always visible; user state can never hide it</td></tr></tbody></table><h2 id="filters-have-authorization-too" tabindex="-1">Filters have authorization too <a class="header-anchor" href="#filters-have-authorization-too" aria-label="Permalink to &quot;Filters have authorization too&quot;">​</a></h2><p><code>Filter::visible()</code> (optional) governs a filter the same way <code>Column::visible()</code> governs a column. A filter with no explicit <code>visible()</code> call automatically inherits authorization from a column sharing its exact key, if one exists — so <code>TextFilter::make(&#39;credit_limit&#39;)</code> is unauthorized whenever the <code>credit_limit</code> column is. A filter-only field with no matching column needs its own explicit <code>-&gt;visible(...)</code> to be authorization-gated; without one it defaults to authorized, same as <code>Column</code>. See <a href="./security#filter-authorization">security.md</a> for the full resolution order and <a href="./filters">filters.md</a> for examples.</p><h2 id="visible-is-checked-everywhere-✅-implemented-hardened" tabindex="-1"><code>visible()</code> is checked everywhere (✅ Implemented, hardened) <a class="header-anchor" href="#visible-is-checked-everywhere-✅-implemented-hardened" aria-label="Permalink to &quot;`visible()` is checked everywhere (✅ Implemented, hardened)&quot;">​</a></h2><p><code>TableDefinition::column(string $key)</code> — the single lookup path used by the query engine, the Livewire component, and preference/view normalization — returns <code>null</code> for a key that exists but whose <code>visible()</code> is currently <code>false</code>. Every caller therefore already treats it as absent. This is enforced by <code>TableState::normalizeVisibleColumns()</code>/<code>normalizeColumnOrder()</code>, which build their allow-list from <code>TableDefinition::authorizedColumns()</code> (only <code>isVisible()</code> columns), not the full column set.</p><p>An unauthorized column is excluded from:</p><ul><li>Rendering (HTML)</li><li>SQL <code>select</code></li><li>Relationship eager loading (<code>RelationColumn</code> behind an unauthorized flag is never eager-loaded)</li><li>Global search</li><li>Filters (sort request for an unauthorized column is silently dropped)</li><li>Sorting</li><li>Export (once implemented — the flag exists, see <a href="./columns">columns.md</a>)</li><li>User preferences (<code>TablePreferences::normalize()</code> re-checks authorization on every load)</li><li>Saved views (re-normalized against the live definition, via the same <code>TableState::normalize()</code>)</li><li>Column manager UI</li><li>Query-string state</li></ul><p><strong>No amount of client-side tampering changes this.</strong> The engine&#39;s tests explicitly try to force an unauthorized column&#39;s key into <code>visibleColumns</code>, <code>columnOrder</code>, and <code>sorts</code> state and assert it never reaches the compiled SQL — see <code>tests/Feature/DynamicTable/SecurityHardeningTest.php</code>.</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">TextColumn</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;credit_limit&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">label</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Credit Limit&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">visible</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> =&gt; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">can</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;view_credit_limits&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span></code></pre></div><p>If the current user can&#39;t view credit limits, this column is invisible in the truest sense — the underlying <code>credit_limit</code> field is never even fetched from the database for that request.</p><h2 id="hiddenbydefault-vs-visible-false" tabindex="-1"><code>hiddenByDefault()</code> vs <code>visible(false)</code> <a class="header-anchor" href="#hiddenbydefault-vs-visible-false" aria-label="Permalink to &quot;`hiddenByDefault()` vs `visible(false)`&quot;">​</a></h2><p>These are unrelated:</p><ul><li><code>hiddenByDefault()</code> — the column is fully authorized and fully functional; it&#39;s just not shown until the user opts in. It still participates in search/sort/filter if configured to.</li><li><code>visible(false)</code> — authorization is revoked. The column does not exist for this request, period.</li></ul><h2 id="toggleable-false-—-fixed-columns" tabindex="-1"><code>toggleable(false)</code> — fixed columns <a class="header-anchor" href="#toggleable-false-—-fixed-columns" aria-label="Permalink to &quot;`toggleable(false)` — fixed columns&quot;">​</a></h2><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">TextColumn</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;id&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toggleable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>A fixed column is always in <code>visibleColumns</code> regardless of what the client sends, and <code>Table::toggleColumn()</code> silently no-ops if called on it. In preference/column-order normalization, fixed columns are always placed first in <code>columnOrder</code> (<code>TablePreferences::normalize()</code>).</p><h2 id="testing-your-own-authorization-callbacks" tabindex="-1">Testing your own authorization callbacks <a class="header-anchor" href="#testing-your-own-authorization-callbacks" aria-label="Permalink to &quot;Testing your own authorization callbacks&quot;">​</a></h2><p>Because <code>visible()</code> accepts a closure evaluated per-request (not cached), it&#39;s safe to check <code>auth()-&gt;user()-&gt;can(...)</code> directly:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">BooleanColumn</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;is_flagged&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">visible</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> =&gt; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">auth</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hasRole</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;admin&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span></code></pre></div><p>See <a href="./testing">testing.md</a> for how to assert a column is genuinely absent as a different user.</p>',23)])])}const u=e(l,[["render",n]]);export{k as __pageData,u as default};
